import json

with open("/home/ubuntu/.claude-account-4/projects/-home-ubuntu--agent-ml-research-idea-gen-0509-3-projects-solver-trace-ablation--claude-sessions-agent-d44a3988/84bc9d0d-4cc8-4918-a8ae-6acbe5812648/tool-results/mcp-agent-ml-research-read_registry-1778805262171.txt") as f:
    outer = json.load(f)

registry = json.loads(outer["result"])
data = registry["data"]
experiments = data["experiments"]

# Show full details for the two active experiments
for eid in ["exp1-isr-b03-s44-r2", "exp1-random-b03-s44"]:
    if eid in experiments:
        exp = experiments[eid]
        print(f"=== {eid} ===")
        # Print all top-level keys except very large nested objects
        for k, v in exp.items():
            if k == "spec":
                print(f"  spec:")
                for sk, sv in v.items():
                    print(f"    {sk}: {sv}")
            elif k == "metrics":
                if v:
                    print(f"  metrics: {json.dumps(v)[:500]}")
                else:
                    print(f"  metrics: (empty)")
            else:
                print(f"  {k}: {v}")
        print()

# Also check if there's a 'hypothesis' or 'plan_id' in any experiment
print("=== Experiments with hypothesis field set ===")
for eid, exp in experiments.items():
    h = exp.get("hypothesis")
    if h:
        print(f"  {eid}: {h}")

print()
print("=== Experiments with plan_id field set ===")
for eid, exp in experiments.items():
    p = exp.get("plan_id")
    if p:
        print(f"  {eid}: plan_id={p}")

